Definition chunk_ok (G : list (Z * Z)) (ch : achunk) : Prop :=
  match ch with
  | CPrim c _ => 1 <= c <= 31
  | CSec mb ms n => In (mb, ms) G /\ 0 < mb /\ 0 <= n /\ PG + rz_size n + n <= ms
  end.

