Lemma evq_recycle_chunks : forall {R} RP ga G l st (k : astate -> AM R) extra,
  LW st -> Forall (chunk_ok G) l -> 0 <= extra ->
  (forall st', LW st' -> frq st st' -> PHI st' <= PHI st -> evq RP ga G (PHI st' + extra) (k st')) ->
